html:
{{ print_control(doc) }}
{%- macro v(value) -%}{{ (value or "") | e }}{%- endmacro -%}
{%- macro n(value) -%}{{ "{:,.0f}".format(value | float) if value not in (None, "") else "" }}{%- endmacro -%}
{%- macro pct(value) -%}{{ ("{:.0f}%".format(value | float)) if value not in (None, "") else "" }}{%- endmacro -%}
<style>
.lpl-form { font-family: Cambria, Georgia, serif; font-size: 11px; color: #000; line-height: 1.4; }
.lpl-form table { width: 100%; border-collapse: collapse; margin: 0 0 12px; }
.lpl-form tr { page-break-inside: avoid; }
.lpl-form th, .lpl-form td { border: 1px solid #000; padding: 3px 5px; vertical-align: top; text-align: left; }
.lpl-form th { background: #f2f2f2; font-weight: bold; }
.lpl-form h3 { font-size: 13px; text-align: center; text-transform: uppercase; margin: 6px 0 4px; }
.lpl-form h4 { font-size: 11.5px; font-weight: bold; margin: 14px 0 6px; text-transform: uppercase; }
.lpl-form .sub { text-align: center; margin: 0 0 12px; }
.lpl-form .num { text-align: right; }
.lpl-form .grid td { text-align: center; height: 44px; width: 27%; }
.lpl-form .grid .axis { width: 19%; font-weight: bold; background: #f2f2f2; }
.lpl-form .tiles td { text-align: center; width: 12.5%; }
.lpl-form .tiles b { display: block; font-size: 15px; }
.lpl-form .muted { color: #444; font-size: 10px; }
.lpl-form .pre { white-space: pre-wrap; }
.lpl-form .sign td { border: none; padding: 18px 6px 0 0; width: 50%; }
.lpl-form .sign .line { border-top: 1px solid #000; padding-top: 3px; }
.lpl-form .break { page-break-before: always; }
</style>
{%- set pack = talent_council_pack(doc.name) -%}
<div class="lpl-form">
<h3>Talent Council Pack</h3>
<p class="sub">{{ v(doc.title or doc.name) }}{% if doc.review_year %}, {{ doc.review_year }}{% endif %}. {{ v(doc.status) }}.
{% if pack.before %}Compared with {{ v(pack.before) }}.{% endif %} Printed {{ frappe.utils.format_date(frappe.utils.today()) }}.</p>
{%- if not pack %}
<p>The pack is for HR, the Talent Council and the executives.</p>
{%- else %}
<table class="tiles"><tr>
{%- for tile in pack.kpis %}<td><b>{{ v(tile.value) }}</b>{{ v(tile.label) }}<div class="muted">{{ v(tile.note) }}</div></td>{%- endfor %}
</tr></table>

<h4>The Nine Boxes, the Company</h4>
{%- set company = pack.by_plant[0] if pack.by_plant else {} -%}
<table class="grid">
{%- for line in pack.rows %}
<tr><th class="axis">{{ ["High", "Moderate", "Low"][loop.index0] }} potential</th>
{%- for box in line %}{%- set cell = ((company.boxes or []) | selectattr("box", "equalto", box) | first) or {} -%}
<td><b>{{ box }} {{ v(pack.names.get(box)) }}</b><br>{{ n(cell.n) }} people, {{ pct(cell.share) }}
<span class="muted">(guide {{ pct(cell.guide) }}{% if cell.last_share is not none %}, before {{ pct(cell.last_share) }}{% endif %})</span></td>
{%- endfor %}</tr>
{%- endfor %}
<tr><th class="axis"></th><th>Low</th><th>Meeting</th><th>Exceeding</th></tr>
<tr><th class="axis"></th><th colspan="3">Performance</th></tr>
</table>

<h4>Plants Side by Side</h4>
<table>
<tr><th>Plant</th><th class="num">People</th>{% for box in range(1, 10) %}<th class="num">{{ box }}</th>{% endfor %}<th class="num">Top Talent</th></tr>
{%- for group in pack.by_plant %}
<tr><td>{{ v(group.group) }}</td><td class="num">{{ n(group.total) }}</td>
{%- for row in group.boxes %}<td class="num">{{ pct(row.share) }}</td>{%- endfor %}<td class="num">{{ pct(group.top_share) }}</td></tr>
{%- endfor %}
{%- if company.boxes %}<tr><th>Guide</th><td></td>{% for row in company.boxes %}<td class="num">{{ pct(row.guide) }}</td>{% endfor %}<td></td></tr>{% endif %}
</table>

<h4 class="break">Top Talent</h4>
<table>
<tr><th>Name</th><th>Job Title</th><th>Plant</th><th>Box</th><th class="num">Performance</th><th class="num">Potential</th><th>Flight Risk</th></tr>
{%- for row in pack.top[:20] %}
<tr><td>{{ v(row.employee_name) }}</td><td>{{ v(row.designation) }}</td><td>{{ v(row.branch) }}</td><td>{{ row.box }} {{ v(row.box_name) }}</td>
<td class="num">{{ n(row.performance_score) }}</td><td class="num">{{ n(row.potential_score) }}</td><td>{{ v(row.flight_risk) }}</td></tr>
{%- else %}<tr><td colspan="7">No top talent placed yet.</td></tr>{%- endfor %}
</table>

<h4>Flight Risks</h4>
<table>
<tr><th>Name</th><th>Job Title</th><th>Plant</th><th>Box</th><th>Flight Risk</th><th>Impact of Loss</th><th class="num">Retention Actions Open</th></tr>
{%- for row in pack.risk[:20] %}
<tr><td>{{ v(row.employee_name) }}</td><td>{{ v(row.designation) }}</td><td>{{ v(row.branch) }}</td><td>{{ row.box }}</td>
<td>{{ v(row.flight_risk) }}</td><td>{{ v(row.impact_of_loss) }}</td><td class="num">{{ row.actions or "None" }}</td></tr>
{%- else %}<tr><td colspan="7">Nobody at a watched flight risk.</td></tr>{%- endfor %}
</table>

<h4 class="break">Succession Coverage</h4>
<p>{{ n(pack.bench.roles) }} critical roles: {{ pct(pack.bench.ready_now_share) }} have a successor ready now,
{{ pct(pack.bench.two_share) }} have two or more named, {{ n(pack.bench.none) }} have nobody.
{{ pack.overlap | length }} successor(s) are named for more than one role.</p>
<table class="grid">
<tr><th class="axis">Impact</th><th>Low probability</th><th>Medium</th><th>High</th></tr>
{%- for line in pack.heat.rows %}
<tr><th class="axis">{{ line.impact }}</th>{% for cell in line.cells %}<td><b>{{ cell.count }}</b></td>{% endfor %}</tr>
{%- endfor %}
</table>
<table>
<tr><th>Role</th><th>Plant</th><th>Holder</th><th class="num">Role Risk</th><th>Coverage</th><th class="num">Ready Now</th></tr>
{%- for row in pack.roles[:12] %}
<tr><td>{{ v(row.designation) }}</td><td>{{ v(row.branch) }}</td><td>{{ v(row.incumbent_name) }}</td>
<td class="num">{{ n(row.role_risk) }}</td><td>{{ v(row.coverage) }}</td><td class="num">{{ row.ready_now or 0 }}</td></tr>
{%- endfor %}
</table>

<h4>Movement Since the Review Before</h4>
{%- if pack.before %}
<p>Stayed {{ pack.movement.same }}, up {{ pack.movement.up }}, down {{ pack.movement.down }}, across {{ pack.movement.across }},
new {{ pack.movement.new }}, left {{ pack.movement.gone }}.</p>
{%- else %}<p>There is no earlier review to compare with.</p>{%- endif %}

<h4>Graduate Pipeline</h4>
<table>
<tr><th>Cohort</th><th class="num">Trainees</th><th class="num">Recruited</th><th class="num">Induction</th><th class="num">Rotation</th>
<th class="num">Assessment</th><th class="num">Confirmed</th><th class="num">Left</th></tr>
{%- for row in pack.funnel %}
<tr><td>{{ v(row.cohort) }}</td><td class="num">{{ row.total }}</td>
{%- for stage in ["Recruited", "In Induction", "In Rotation", "Under Assessment", "Confirmed", "Exited"] %}<td class="num">{{ row.stages[stage] }}</td>{% endfor %}</tr>
{%- else %}<tr><td colspan="8">No graduate trainees.</td></tr>{%- endfor %}
</table>

<h4>Decisions</h4>
<table>
<tr><th style="width:34%">Placements Finalised</th><th style="width:33%">Successors</th><th style="width:33%">Talent Pools</th></tr>
<tr><td>{% for row in pack.decisions.placements %}{{ v(row.decision or "None") }}: {{ row.n }}<br>{% endfor %}</td>
<td>{% for row in pack.decisions.successors %}{{ v(row.decision or "Not decided") }}: {{ row.n }}<br>{% endfor %}</td>
<td>{% for row in pack.decisions.pools %}{{ v(row.pool_name) }}: {{ v(row.status) }}, {{ row.active_members or 0 }} members<br>{% endfor %}</td></tr>
</table>
<p>Development plans: {{ n(pack.investment.approved) }} approved, {{ n(pack.investment.actual) }} spent over {{ pack.investment.plans }} plans.
{{ pack.decisions.gaps_recruited }} confirmed gap(s) are being recruited for.</p>
{%- if pack.remarks %}<p><b>Council's remarks</b></p><div class="pre">{{ v(pack.remarks) }}</div>{%- endif %}
<table class="sign"><tr>
<td><div class="line">Chair, Talent Council</div><span class="muted">Date</span></td>
<td><div class="line">HR Manager</div><span class="muted">Date</span></td>
</tr></table>
{%- endif %}
</div>
